def banco_cambios():
    nombres = [t(*c[0]) for c in CAMBIOS]
    sit = [
        (t("A puddle dries up on a sunny afternoon.", "Un charco se seca en una tarde soleada."), 2), (t("Butter softens and runs in a hot pan.", "La mantequilla se ablanda y se derrite en una sartén caliente."), 0),
        (t("Your breath fogs a cold window.", "El aliento empaña una ventana fría."), 3), (t("Mothballs in a closet slowly shrink and disappear, with no liquid.", "Las bolitas de naftalina de un armario encogen y desaparecen poco a poco, sin dejar líquido."), 4),
        (t("Water in an ice cube tray turns hard overnight.", "El agua de una cubitera se pone dura durante la noche."), 1), (t("Ice crystals form on the inside of a freezer from the air.", "Se forman cristales de hielo en el interior del congelador a partir del aire."), 5),
        (t("Melted candle wax drips and turns solid again.", "La cera derretida de una vela gotea y se vuelve sólida otra vez."), 1), (t("A pot of soup boils and steam rises.", "Una olla de sopa hierve y sube el vapor."), 2),
    ]
    out = [{"enun": t("Which change of state is this?", "¿Qué cambio de estado es este?") + f"<br><strong>{x}</strong>", "ops": nombres, "ok": k, "enOrden": True,
            "pista": t("What is the starting state, and what is the final state?", "¿Cuál es el estado de partida y cuál el de llegada?"), "exp": f"<strong>{nombres[k]}</strong>: {t(*CAMBIOS[k][1]).lower()} → {t(*CAMBIOS[k][2]).lower()}. " + t(*CAMBIOS[k][3]) + t(" heat.", " calor.")} for x, k in sit]
    for i, c in enumerate(CAMBIOS):
        ab = c[3][0] == "Absorbs"
        out.append({"enun": t(f"Does <strong>{c[0][0].lower()}</strong> absorb or release heat?", f"La <strong>{c[0][1].lower()}</strong>, ¿absorbe o libera calor?"), "ops": [t("It absorbs heat", "Absorbe calor"), t("It releases heat", "Libera calor")], "ok": 0 if ab else 1, "enOrden": True,
                    "pista": t("Toward more energy (solid → liquid → gas) absorbs; the other way releases.", "Hacia más energía (sólido → líquido → gas) absorbe; al revés, libera."),
                    "exp": t(f"{c[1][0]} → {c[2][0]}: ", f"{c[1][1]} → {c[2][1]}: ") + (t("toward more energy, so it absorbs heat.", "hacia más energía, así que absorbe calor.") if ab else t("toward less energy, so it releases heat.", "hacia menos energía, así que libera calor."))})
    return out


