        (t("On the plateau at 0 °C, what is in the container?", "En la meseta de 0 °C, ¿qué hay en el recipiente?"), [t("Ice and liquid water together", "Hielo y agua líquida a la vez"), t("Only ice", "Solo hielo"), t("Only liquid water", "Solo agua líquida")], 0, t("A plateau means two states together.", "Una meseta indica dos estados a la vez.")),
        (t("On the slope between 0 °C and 100 °C, what is happening?", "En el tramo entre 0 °C y 100 °C, ¿qué ocurre?"), [t("Liquid water is getting hotter", "El agua líquida se calienta"), t("Water is boiling", "El agua hierve"), t("Ice is melting", "El hielo se funde")], 0, t("A slope means one state warming up.", "Un tramo inclinado es un solo estado que se calienta.")),
