def densidad():
    """Problemas exactos: hallar d, m o V."""
    rnd = random.Random(52)
    mats = [(("aluminum", "aluminio"), "2.7"), (("iron", "hierro"), "7.9"), (("pine wood", "madera de pino"), "0.5"), (("cooking oil", "aceite"), "0.92"), (("ice", "hielo"), "0.92"),
            (("copper", "cobre"), "8.9"), (("glass", "vidrio"), "2.5"), (("milk", "leche"), "1.03"), (("cork", "corcho"), "0.24"), (("gold", "oro"), "19.3")]
    out = []
    for n in range(30):
        (mn, ds) = mats[n % len(mats)]
        d = D(ds); V = D(rnd.choice([5, 10, 20, 25, 40, 50, 80, 100, 200, 250])); m = d * V
        nom = t(*mn)
        fl = t("floats", "flota") if d < 1 else t("sinks", "se hunde")
        un = "mL" if mn[0] in ("cooking oil", "milk") else "cm³"
        q = n % 3
        fmt = lambda x: format(x.normalize(), "f")
        if q == 0:
            enun = t(f"A sample of {nom} has a mass of <strong>{fmt(m)} g</strong> and a volume of <strong>{fmt(V)} {un}</strong>. What is its <strong>density</strong> (g/{un})?", f"Una muestra de {nom} tiene una masa de <strong>{fmt(m)} g</strong> y un volumen de <strong>{fmt(V)} {un}</strong>. ¿Cuál es su <strong>densidad</strong> (g/{un})?")
            r, exp = fmt(d), t(f"d = m ÷ V = {fmt(m)} ÷ {fmt(V)} = {fmt(d)} g/{un}. It {fl} in water.", f"d = m ÷ V = {fmt(m)} ÷ {fmt(V)} = {fmt(d)} g/{un}. En agua, {fl}.")
        elif q == 1:
            enun = t(f"The density of {nom} is <strong>{fmt(d)} g/{un}</strong>. What is the <strong>mass</strong> (g) of <strong>{fmt(V)} {un}</strong>?", f"La densidad del {nom} es <strong>{fmt(d)} g/{un}</strong>. ¿Qué <strong>masa</strong> (g) tienen <strong>{fmt(V)} {un}</strong>?")
            r, exp = fmt(m), t(f"m = d × V = {fmt(d)} × {fmt(V)} = {fmt(m)} g.", f"m = d × V = {fmt(d)} × {fmt(V)} = {fmt(m)} g.")
        else:
            enun = t(f"A sample of {nom} has a mass of <strong>{fmt(m)} g</strong>. Its density is <strong>{fmt(d)} g/{un}</strong>. What <strong>volume</strong> ({un}) does it take up?", f"Una muestra de {nom} tiene una masa de <strong>{fmt(m)} g</strong>. Su densidad es <strong>{fmt(d)} g/{un}</strong>. ¿Qué <strong>volumen</strong> ({un}) ocupa?")
            r, exp = fmt(V), t(f"V = m ÷ d = {fmt(m)} ÷ {fmt(d)} = {fmt(V)} {un}.", f"V = m ÷ d = {fmt(m)} ÷ {fmt(d)} = {fmt(V)} {un}.")
        if C.L == "es":
            enun = enun.replace("del aceite", "del aceite").replace("La densidad del leche", "La densidad de la leche").replace("La densidad del madera", "La densidad de la madera")
        out.append({"enun": f"<p>{enun}</p>", "r": r, "exp": exp})
    return out


def banco_flota():
    rnd = random.Random(53)
    out = []
    for _ in range(14):
        V = rnd.choice([10, 20, 25, 40, 50, 80, 100])
        d = rnd.choice([D("0.3"), D("0.5"), D("0.6"), D("0.8"), D("0.9"), D("1.2"), D("1.5"), D("2.5"), D("3"), D("8")])
        m = d * V
        f = lambda x: format(x.normalize(), "f")
        fl = d < 1
        out.append({"enun": t(f"An object has a mass of <strong>{f(m)} g</strong> and a volume of <strong>{V} cm³</strong>. In water, it…", f"Un objeto tiene una masa de <strong>{f(m)} g</strong> y un volumen de <strong>{V} cm³</strong>. En agua…"),
                    "ops": [t("floats", "flota"), t("sinks", "se hunde")], "ok": 0 if fl else 1, "enOrden": True, "pista": t("Find d = m ÷ V and compare with 1.00.", "Halle d = m ÷ V y compare con 1.00."),
                    "exp": t(f"d = {f(m)} ÷ {V} = {f(d)} g/cm³, " + ("less than 1.00: it floats." if fl else "more than 1.00: it sinks."), f"d = {f(m)} ÷ {V} = {f(d)} g/cm³, " + ("menor que 1.00: flota." if fl else "mayor que 1.00: se hunde."))})
    out += [
        {"enun": t("Two blocks of the same wood: one is large and one is small. In water…", "Dos bloques de la misma madera: uno grande y otro pequeño. En agua…"), "ops": [t("both float, because they have the same density", "los dos flotan, porque tienen la misma densidad"), t("the large one sinks because it is heavier", "el grande se hunde porque pesa más"), t("the small one sinks", "el pequeño se hunde")], "ok": 0, "pista": t("Does cutting a piece change its density?", "¿Cortar un trozo cambia su densidad?"), "exp": t("Density is a property of the material, not of the size.", "La densidad es propiedad del material, no del tamaño.")},
        {"enun": t("Oil and water are poured into a glass. Which liquid ends up on top?", "Se vierten aceite y agua en un vaso. ¿Qué líquido queda arriba?"), "ops": [t("Oil (0.92 g/mL)", "El aceite (0.92 g/mL)"), t("Water (1.00 g/mL)", "El agua (1.00 g/mL)"), t("They mix evenly", "Se mezclan por igual")], "ok": 0, "pista": t("The less dense one rises.", "El menos denso sube."), "exp": t("Less dense on top.", "El menos denso, arriba.")},
    ]
    return out


def clasif_mezclas():
    G = [t("Pure substance", "Sustancia pura"), t("Solution (homogeneous mixture)", "Disolución (mezcla homogénea)"), t("Heterogeneous mixture", "Mezcla heterogénea")]
    P = [t("Only one kind of matter?", "¿Un solo tipo de materia?"), t("Mixed evenly, one phase?", "¿Mezclado por igual, una sola fase?"), t("Can you see the parts?", "¿Se distinguen las partes?")]
    def item(tit, piezas):
        return {"titulo": tit, "intro": t("Sort each example.", "Clasifique cada ejemplo."), "grupos": G, "etiqueta": t("Kind:", "Tipo:"), "piezas": [{"t": a, "v": v, "pista": P[v]} for a, v in piezas],
                "extra": t("Pure = one kind; solution = even mix; heterogeneous = visible parts.", "Pura = un tipo; disolución = mezcla uniforme; heterogénea = partes visibles.")}
    return [
        item(t("Set 1", "Grupo 1"), [(t("Distilled water", "Agua destilada"), 0), (t("Sugar dissolved in tea", "Azúcar disuelta en té"), 1), (t("Vegetable soup", "Sopa de verduras"), 2), (t("A bar of pure gold", "Un lingote de oro puro"), 0), (t("Air", "El aire"), 1)]),
        item(t("Set 2", "Grupo 2"), [(t("Oil and vinegar salad dressing", "Aliño de aceite y vinagre"), 2), (t("Steel (iron with a little carbon, evenly mixed)", "Acero (hierro con algo de carbono, mezclado por igual)"), 1), (t("Table salt (NaCl)", "Sal común (NaCl)"), 0), (t("Granite, with grains of different colors", "Granito, con granos de distintos colores"), 2), (t("Salt water", "Agua salada"), 1)]),
    ]


def banco_solubilidad():
    curvas = [
        (t("Potassium nitrate (a solid)", "Nitrato de potasio (un sólido)"), [[0, 13], [20, 32], [40, 64], [60, 110], [80, 169]], "s", 40, 20),
        (t("Sugar (a solid)", "Azúcar (un sólido)"), [[0, 180], [20, 200], [40, 240], [60, 290], [80, 360]], "s", 50, 20),
        (t("Oxygen (a gas), in milligrams", "Oxígeno (un gas), en miligramos"), [[0, 15], [10, 11], [20, 9], [30, 8], [40, 6]], "g", 5, 10),
    ]
    out = []
    for nom, pts, tipo, py, px in curvas:
        sp = {"tipo": "linea", "xEtq": t("Water temperature (°C)", "Temperatura del agua (°C)"), "yEtq": t("Amount dissolved", "Cantidad disuelta"), "px": px, "py": py, "series": [{"nombre": "", "puntos": pts}]}
        g = f"<p><strong>{nom}</strong> · " + t("per 100 g of water", "por cada 100 g de agua") + "</p>" + C.grafica(sp, C.describe(sp), ancho=520, alto=290, y0=0)
        x, y = pts[2]
        out.append({"enun": g + "<p><strong>" + t(f"How much dissolves at {x} °C?", f"¿Cuánto se disuelve a {x} °C?") + "</strong></p>", "ops": [str(y), str(pts[1][1]), str(pts[3][1]), str(pts[4][1])], "ok": 0,
                    "pista": t("Go up from the temperature to the line, then across.", "Suba desde la temperatura hasta la línea y lea a la izquierda."), "exp": t(f"At {x} °C the curve is at {y}.", f"A {x} °C la curva está en {y}.")})
        tend = t("More heat, more dissolves (a solid)", "Más calor, más se disuelve (un sólido)") if tipo == "s" else t("More heat, less dissolves (a gas)", "Más calor, menos se disuelve (un gas)")
        otra = t("More heat, less dissolves (a gas)", "Más calor, menos se disuelve (un gas)") if tipo == "s" else t("More heat, more dissolves (a solid)", "Más calor, más se disuelve (un sólido)")
        out.append({"enun": g + "<p><strong>" + t("What does the curve show?", "¿Qué muestra la curva?") + "</strong></p>", "ops": [tend, otra, t("Temperature makes no difference", "La temperatura no influye")], "ok": 0,
                    "pista": t("Does the line go up or down to the right?", "¿La línea sube o baja hacia la derecha?"), "exp": tend + "."})
        menos = y - (5 if tipo == "s" else 2)
        out.append({"enun": g + "<p><strong>" + t(f"At {x} °C, a solution has {menos} dissolved. It is…", f"A {x} °C, una disolución tiene {menos} disuelto. Es…") + "</strong></p>",
                    "ops": [t("unsaturated", "insaturada"), t("saturated", "saturada"), t("supersaturated", "sobresaturada")], "ok": 0, "enOrden": True,
                    "pista": t("Is the point below, on, or above the curve?", "¿El punto está debajo, sobre o encima de la curva?"), "exp": t(f"{menos} is below the curve ({y}): it can take more.", f"{menos} está debajo de la curva ({y}): admite más.")})
        out.append({"enun": g + "<p><strong>" + t(f"At {x} °C, a solution has exactly {y} dissolved. It is…", f"A {x} °C, una disolución tiene exactamente {y} disuelto. Es…") + "</strong></p>",
                    "ops": [t("unsaturated", "insaturada"), t("saturated", "saturada"), t("supersaturated", "sobresaturada")], "ok": 1, "enOrden": True,
                    "pista": t("Is the point below, on, or above the curve?", "¿El punto está debajo, sobre o encima de la curva?"), "exp": t("On the curve: saturated.", "Sobre la curva: saturada.")})
    return out


def practica():
    A = {"en": ["changes", "heating-curve", "density", "float-sink", "mixtures", "solubility"], "es": ["cambios", "curva", "densidad", "flota-hunde", "mezclas", "solubilidad"]}[C.L]
    mods = [
        (A[0], t("Name the change of state", "Nombre el cambio de estado"), C.om("m1", t("From where to where? And does it absorb or release heat?", "¿De dónde a dónde? ¿Y absorbe o libera calor?"))),
        (A[1], t("Read the heating curve", "Lea la curva de calentamiento"), C.om("m2", t("Slopes and plateaus.", "Tramos inclinados y mesetas."))),
        (A[2], t("Density problems", "Problemas de densidad"), "      <p>" + t("Decide what is missing, choose the form of the formula, and write only the number (the unit is given in the question).", "Decida qué falta, elija la forma de la fórmula y escriba solo el número (la unidad está en la pregunta).") + "</p>\n" + C.dec_campo("m3", t("Answer", "Respuesta"))),
        (A[3], t("Float or sink?", "¿Flota o se hunde?"), C.om("m4", t("Find the density and compare with 1.00 g/cm³.", "Halle la densidad y compare con 1.00 g/cm³."))),
        (A[4], t("Pure substance or mixture?", "¿Sustancia pura o mezcla?"), C.clasifica("m5", t("Sort each example.", "Clasifique cada ejemplo."))),
        (A[5], t("Read solubility curves", "Lea curvas de solubilidad"), C.om("m6", t("Two solids and a gas.", "Dos sólidos y un gas."))),
    ]
    pista = t("d = m ÷ V · m = d × V · V = m ÷ d. Which two values does the question give?", "d = m ÷ V · m = d × V · V = m ÷ d. ¿Qué dos datos da el enunciado?")
    js = (C.js_datos("CAM", banco_cambios()) + C.js_datos("CUR", banco_curva()) + C.js_datos("DEN", densidad()) + C.js_datos("FLO", banco_flota()) + C.js_datos("MEZ", clasif_mezclas()) + C.js_datos("SOL", banco_solubilidad()) +
          f"var sacaD = mazo(DEN), PD = {C.json.dumps(pista, ensure_ascii=False)};\nfunction gD(){{ var q = sacaD(); return {{enun: q.enun, resp: leeNumero(q.r), explica: q.exp, pista: function(){{ return PD; }}}}; }}\n" +
          'creaBanco("m1", CAM);\ncreaBanco("m2", CUR);\ncreaPracticaDec("m3", gD);\ncreaBanco("m4", FLO);\ncreaClasifica("m5", MEZ);\ncreaBanco("m6", SOL);\n')
    return C.pagina_practica(N, titulo(), t("Six activities · new exercises every time · two tries in each one · calculator included", "Seis actividades · ejercicios nuevos cada vez · dos intentos en cada uno · con calculadora"),
                             mods, js, scripts=("/math/scinot.js",), calculadora=True)


if __name__ == "__main__":
    C.construye(N, leccion, practica)
